const ofxData = (d: Date) => `${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, '0')}${String(d.getUTCDate()).padStart(2, '0')}120000`

function cpfValido(seed: number): string {
  const n = String(100000000 + (seed % 899999999)).slice(0, 9).split('').map(Number)
  const dv = (arr: number[]) => { const s = arr.reduce((a, x, i) => a + x * (arr.length + 1 - i), 0); const r = (s * 10) % 11; return r === 10 ? 0 : r }
  const d1 = dv(n); const d2 = dv([...n, d1])
  return [...n, d1, d2].join('')
}

