  check('transferência não altera o saldo total', (await call(fin, 'GET', `${TS}/contas`)).json.saldoTotal === 100500)
  check('transferência para a mesma conta recusada', (await call(fin, 'POST', `${TS}/transferencias`, { origemId: idB, destinoId: idB, valor: 10 })).status === 400)
  check('tarifa reduz saldo', (await call(fin, 'POST', `${TS}/movimentos`, { contaId: idB, tipo: 'TARIFA', valor: 45.9, descricao: 'Tarifa mensal' })).status === 201 && (await call(fin, 'GET', `${TS}/contas`)).json.items.find((x: any) => x.id === idB).saldo === 98954.1)
  check('rendimento aumenta saldo', (await call(fin, 'POST', `${TS}/movimentos`, { contaId: idB, tipo: 'RENDIMENTO', valor: 45.9, descricao: 'Rendimento' })).status === 201)
  const conf = await call(fin, 'POST', `${TS}/contas/${idB}/conferir-saldo`, { saldoBanco: 99100 })
  check('conferência de saldo mostra diferença', conf.status === 200 && conf.json.saldoSistema === 99000 && conf.json.diferenca === 100, conf.json)
  const ext = await call(fin, 'GET', `${TS}/contas/${idB}/extrato-sistema`)
  check('extrato do sistema lista movimentos', ext.status === 200 && ext.json.total >= 3)
  check('conta de outro tenant = 404', (await call(finB, 'GET', `${TS}/contas/${idB}/extrato-sistema`)).status === 404)
  check('outro tenant não vê contas', (await call(finB, 'GET', `${TS}/contas`)).json.items.length === 0)

  // ---------------------------------------------------------------- configuração e alçadas
  secao('Configuração e alçadas')
  const cfg = await call(fin, 'GET', `${TS}/config`)
  check('config padrão com alçadas padrão', cfg.status === 200 && cfg.json.alcadasPadrao === true && cfg.json.alcadas.length === 3 && cfg.json.config.limiteDuplaAprovacao === 20000)
  check('config atualizada pelo financeiro', (await call(fin, 'PUT', `${TS}/config`, { regimeTributario: 'SIMPLES', serieRecibo: 'B', sistemaContabil: 'Contabilizei' })).status === 200)
  check('regime inválido recusado', (await call(fin, 'PUT', `${TS}/config`, { regimeTributario: 'XYZ' })).status === 400)
  check('financeiro não altera alçadas', (await call(fin, 'PUT', `${TS}/alcadas`, { faixas: [{ nome: 'Tudo', valorAte: null, papeis: ['FINANCE'], aprovacoes: 1 }] })).status === 403)
  check('diretoria define alçadas; última faixa sem limite', (await call(admin, 'PUT', `${TS}/alcadas`, { faixas: [{ nome: 'x', valorAte: 100, papeis: ['FINANCE'] }] })).status === 400)
  check('tetos crescentes', (await call(admin, 'PUT', `${TS}/alcadas`, { faixas: [{ nome: 'a', valorAte: 500, papeis: ['FINANCE'] }, { nome: 'b', valorAte: 100, papeis: ['FINANCE'] }, { nome: 'c', valorAte: null, papeis: ['FINANCE'] }] })).status === 400)
  await call(fin, 'PUT', `${TS}/config`, { serieRecibo: 'A', regimeTributario: 'IMUNE_ISENTA' })

  // ---------------------------------------------------------------- bolsas e mensalidades
  secao('Mensalidades, bolsas aplicadas automaticamente e conferência')
  const prog = await prisma.academicProgram.create({ data: { tenantId: T, nome: 'Odontologia TES', modalidade: 'PRESENCIAL', cargaHorariaTotal: 4000 } })
  const term = await prisma.academicTerm.create({ data: { tenantId: T, codigo: '2026/2-tes', dataInicio: new Date('2026-08-03'), dataFim: new Date('2026-12-18') } })
  const enr = await prisma.enrollment.create({ data: { studentId: aluno.studentId!, programId: prog.id, termId: term.id } })
  const alunoDoc = cpfValido(777)
  await prisma.student.update({ where: { id: aluno.studentId! }, data: { cpf: alunoDoc, nomeCompleto: 'Maria Bolsista Souza' } })
  await prisma.student.update({ where: { id: aluno2.studentId! }, data: { nomeCompleto: 'Pedro Sem Bolsa Lima' } })
  const progBolsa = await prisma.apoProgramaBolsa.create({ data: { tenantId: T, nome: 'Bolsa Mérito 30%', tipo: 'MERITO', percentualDesconto: 30 } })
  const inicioBolsa = new Date(); inicioBolsa.setMonth(inicioBolsa.getMonth() - 1)
  const fimBolsa = new Date(); fimBolsa.setMonth(fimBolsa.getMonth() + 12)
  const concessao = await prisma.apoConcessaoBolsa.create({ data: { tenantId: T, programaId: progBolsa.id, studentId: aluno.studentId!, percentual: 30, inicio: inicioBolsa, fim: fimBolsa, status: 'ATIVA' } })
  const primeiroVenc = new Date(Date.now() + 10 * DAY).toISOString()
  const gm = await call(fin, 'POST', `${TS}/recebiveis/gerar-mensalidades`, { studentId: aluno.studentId, enrollmentId: enr.id, valorParcela: 1000, quantidadeParcelas: 4, diaVencimento: 10, primeiroVencimento: primeiroVenc })
  check('gera 4 mensalidades já com bolsa', gm.status === 201 && gm.json.parcelasGeradas === 4 && gm.json.comBolsa === 4, gm.json)
  check('carnê duplicado recusado', (await call(fin, 'POST', `${TS}/recebiveis/gerar-mensalidades`, { studentId: aluno.studentId, enrollmentId: enr.id, valorParcela: 1000, quantidadeParcelas: 4, diaVencimento: 10, primeiroVencimento: primeiroVenc })).status === 409)
  const gm2 = await call(fin, 'POST', `${TS}/recebiveis/gerar-mensalidades`, { studentId: aluno2.studentId, valorParcela: 800, quantidadeParcelas: 2, diaVencimento: 5, primeiroVencimento: primeiroVenc })
  check('aluno sem bolsa: nenhuma parcela com bolsa', gm2.status === 201 && gm2.json.comBolsa === 0)
  const lr = await call(fin, 'GET', `${TS}/recebiveis?studentId=${aluno.studentId}`)
  check('lista recebíveis com ajuste e valor devido', lr.status === 200 && lr.json.items.length === 4 && lr.json.items[0].valorDevido === 700 && lr.json.items[0].ajuste.bolsaValor === 300 && lr.json.items[0].ajuste.programaNome === 'Bolsa Mérito 30%' && lr.json.items[0].aluno.nomeCompleto.includes('Bolsista'), lr.json.items[0])
  const [r1, r2_, r3, r4] = lr.json.items
  const conf1 = await call(fin, 'GET', `${TS}/bolsas/conferencia`)
  check('conferência de bolsas: tudo conforme', conf1.status === 200 && conf1.json.divergentes === 0 && conf1.json.conferidas >= 4, conf1.json)
  await prisma.apoConcessaoBolsa.update({ where: { id: concessao.id }, data: { status: 'SUSPENSA' } })
  const conf2 = await call(fin, 'GET', `${TS}/bolsas/conferencia`)
  check('conferência detecta bolsa sem concessão vigente', conf2.json.divergentes === 4 && conf2.json.divergencias[0].motivo.includes('sem concessão'), conf2.json.divergencias?.[0])
  check('painel acusa bolsas divergentes', (await call(fin, 'GET', `${TS}/painel`)).json.bolsas.divergentes >= 4)
  const ab = await call(fin, 'POST', `${TS}/recebiveis/aplicar-bolsas`, { studentId: aluno.studentId })
  check('aplicar-bolsas remove a bolsa da concessão suspensa', ab.status === 200 && ab.json.aplicados === 4 && (await call(fin, 'GET', `${TS}/recebiveis?studentId=${aluno.studentId}`)).json.items[0].valorDevido === 1000)
  await prisma.apoConcessaoBolsa.update({ where: { id: concessao.id }, data: { status: 'ATIVA' } })
  const conf3 = await call(fin, 'GET', `${TS}/bolsas/conferencia`)
  check('conferência detecta concessão sem bolsa aplicada', conf3.json.divergentes === 4 && conf3.json.divergencias[0].motivo.includes('sem bolsa aplicada'))
  await call(fin, 'POST', `${TS}/recebiveis/aplicar-bolsas`, {})
  check('reaplicar corrige', (await call(fin, 'GET', `${TS}/bolsas/conferencia`)).json.divergentes === 0)
  const dm = await call(fin, 'PUT', `${TS}/recebiveis/${r4.id}/desconto`, { percentual: 10, motivo: 'Desconto de pontualidade' })
  check('desconto manual soma-se à bolsa', dm.status === 200 && dm.json.descontoValor === 100 && dm.json.valorLiquido === 600 && dm.json.origem === 'MANUAL', dm.json)
  check('desconto exige motivo', (await call(fin, 'PUT', `${TS}/recebiveis/${r4.id}/desconto`, { percentual: 5 })).status === 400)
  const novoRec = await call(fin, 'POST', `${TS}/recebiveis`, { studentId: aluno.studentId, descricao: 'Mensalidade extra 5/12', numeroParcela: 5, valor: 500, dataVencimento: iso(15) })
  check('recebível avulso já nasce com bolsa', novoRec.status === 201 && novoRec.json.ajuste.bolsaValor === 150)
  check('aluno de outro tenant recusado', (await call(finB, 'POST', `${TS}/recebiveis`, { studentId: aluno.studentId, descricao: 'Mensalidade', valor: 10, dataVencimento: iso(1) })).status === 404)

  // ---------------------------------------------------------------- recebimentos por forma
  secao('Recebimentos: Pix, boleto, cartão, dinheiro, transferência, permuta, encargos e recibos')
  const rcPix = await call(fin, 'POST', `${TS}/recebiveis/${r1.id}/receber`, { forma: 'PIX', contaId: idB })
  check('recebe por Pix com bolsa (700)', rcPix.status === 200 && rcPix.json.recebimento.valorRecebido === 700 && rcPix.json.recebimento.bolsa === 300 && rcPix.json.receivable.status === 'PAGO', rcPix.json)
  check('recibo emitido junto, numerado e com extenso', rcPix.json.recibo?.numero === 1 && rcPix.json.recibo.rotulo === 'A-000001' && rcPix.json.recibo.valorExtenso === 'setecentos reais', rcPix.json.recibo)
  check('recebimento duplicado = 409', (await call(fin, 'POST', `${TS}/recebiveis/${r1.id}/receber`, { forma: 'PIX', contaId: idB })).status === 409)
  check('transação e lançamento contábil do financeiro gerados', (await prisma.paymentTransaction.count({ where: { tenantId: T, accountReceivableId: r1.id, tipo: 'RECEITA', valor: 700 } })) === 1 && (await prisma.accountingEntry.count({ where: { tenantId: T, historico: { contains: 'Bolsa/desconto' }, valor: 300 } })) === 1)
  check('saldo do banco aumenta', (await call(fin, 'GET', `${TS}/contas`)).json.items.find((x: any) => x.id === idB).saldo === 99700)
  const rcBol = await call(fin, 'POST', `${TS}/recebiveis/${r2_.id}/receber`, { forma: 'BOLETO', contaId: idB, emitirRecibo: false })
  check('recebe por boleto sem recibo', rcBol.status === 200 && rcBol.json.recibo === null)
  const rcDin = await call(fin, 'POST', `${TS}/recebiveis/${r3.id}/receber`, { forma: 'DINHEIRO', contaId: idB })
  check('dinheiro exige conta CAIXA', rcDin.status === 400)
  const rcDin2 = await call(fin, 'POST', `${TS}/recebiveis/${r3.id}/receber`, { forma: 'DINHEIRO', contaId: idCx })
  check('recebe em dinheiro no caixa', rcDin2.status === 200 && rcDin2.json.recibo.rotulo === 'A-000002')
  const rcSemConta = await call(fin, 'POST', `${TS}/recebiveis/${r4.id}/receber`, { forma: 'CARTAO' })
  check('forma sem conta recusada', rcSemConta.status === 400)
  const rcCartao = await call(fin, 'POST', `${TS}/recebiveis/${r4.id}/receber`, { forma: 'CARTAO', contaId: idB, desconto: 100 })
  check('cartão com desconto extra no ato (600 - 100)', rcCartao.status === 200 && rcCartao.json.recebimento.valorRecebido === 500 && rcCartao.json.recebimento.desconto === 200, rcCartao.json.recebimento)
  const lr2 = await call(fin, 'GET', `${TS}/recebiveis?studentId=${aluno2.studentId}&status=PENDENTE`)
  const [s1, s2] = lr2.json.items
  const rcTr = await call(fin, 'POST', `${TS}/recebiveis/${s1.id}/receber`, { forma: 'TRANSFERENCIA', contaId: idB2, juros: 5, multa: 10 })
  check('transferência com juros e multa informados', rcTr.status === 200 && rcTr.json.recebimento.valorRecebido === 815, rcTr.json.recebimento)
  const rcExc = await call(fin, 'POST', `${TS}/recebiveis/${novoRec.json.id}/receber`, { forma: 'PIX', contaId: idB, desconto: 999 })
  check('desconto maior que o devido recusado', rcExc.status === 400)
  // atraso com encargos automáticos
  const atrasado = await prisma.accountReceivable.create({ data: { tenantId: T, studentId: aluno2.studentId!, descricao: 'Mensalidade 9/12', numeroParcela: 9, valor: 1000, dataVencimento: new Date(Date.now() - 30 * DAY) } })
  const lAtr = await call(fin, 'GET', `${TS}/recebiveis?status=ATRASADO`)
  check('lista atrasados com encargos sugeridos', lAtr.status === 200 && lAtr.json.items.some((i: any) => i.id === atrasado.id && i.status === 'ATRASADO' && i.encargosSugeridos.multa === 20))
  const rcEnc = await call(fin, 'POST', `${TS}/recebiveis/${atrasado.id}/receber`, { forma: 'PIX', contaId: idB, aplicarEncargos: true })
  check('encargos automáticos aplicados', rcEnc.status === 200 && rcEnc.json.recebimento.multa === 20 && rcEnc.json.recebimento.juros >= 9.9 && rcEnc.json.recebimento.valorRecebido > 1029, rcEnc.json.recebimento)

  // permuta no recebimento
  const pmBase = { sentido: 'RECEBER', parteNome: 'Gráfica Rápida Ltda', parteDocumento: '11222333000181', tipoContrapartida: 'SERVICO', descricao: 'Impressão de material institucional', valorEquivalente: 800, documentoTipo: 'CONTRATO', documentoNumero: 'CT-2026/15', dataAcordo: iso(-2) }
  const pm = await call(fin, 'POST', `${TS}/permutas`, { ...pmBase, receivableId: s2.id })
  check('cria permuta em rascunho', pm.status === 201 && pm.json.numero === 'PM-00001' && pm.json.status === 'RASCUNHO', pm.json)
  check('permuta exige documento', (await call(fin, 'POST', `${TS}/permutas`, { ...pmBase, documentoNumero: undefined })).status === 400)
  const rcPmRasc = await call(fin, 'POST', `${TS}/recebiveis/${s2.id}/receber`, { forma: 'PERMUTA', permutaId: pm.json.id })
  check('permuta não aprovada não quita', rcPmRasc.status === 409 && rcPmRasc.json.code === 'PERMUTA_NAO_APROVADA', rcPmRasc.json)
  check('segregação: quem criou a permuta não a aprova', (await call(fin, 'POST', `${TS}/permutas/${pm.json.id}/aprovar`)).status === 403)
  check('coordenador aprova a permuta', (await call(coord, 'POST', `${TS}/permutas/${pm.json.id}/aprovar`)).status === 200)
  check('permuta sem permutaId recusada', (await call(fin, 'POST', `${TS}/recebiveis/${s2.id}/receber`, { forma: 'PERMUTA' })).status === 400)
  const pmErr = await call(fin, 'POST', `${TS}/permutas`, { ...pmBase, valorEquivalente: 799 })
  await call(coord, 'POST', `${TS}/permutas/${pmErr.json.id}/aprovar`)
  const rcPmVal = await call(fin, 'POST', `${TS}/recebiveis/${s2.id}/receber`, { forma: 'PERMUTA', permutaId: pmErr.json.id })
  check('valor equivalente diferente do devido recusado', rcPmVal.status === 409 && rcPmVal.json.code === 'PERMUTA_VALOR', rcPmVal.json)
  const rcPm = await call(fin, 'POST', `${TS}/recebiveis/${s2.id}/receber`, { forma: 'PERMUTA', permutaId: pm.json.id })
  check('recebe por permuta (sem conta bancária)', rcPm.status === 200 && rcPm.json.recebimento.forma === 'PERMUTA' && rcPm.json.recibo.rotulo.startsWith('A-'), rcPm.json)
  const pmDet = await call(fin, 'GET', `${TS}/permutas/${pm.json.id}`)
  check('permuta liquidada com lançamento contábil D bens / C receita', pmDet.json.status === 'LIQUIDADA' && pmDet.json.lancamento?.valor === 800 && pmDet.json.lancamento.contaDebito.codigo === '1.2.9' && pmDet.json.lancamento.contaCredito.codigo === '3.1.1', pmDet.json.lancamento)
  check('permuta liquidada não pode ser reutilizada', (await call(fin, 'POST', `${TS}/recebiveis/${novoRec.json.id}/receber`, { forma: 'PERMUTA', permutaId: pm.json.id })).status === 409)
  check('permuta liquidada não cancela', (await call(fin, 'POST', `${TS}/permutas/${pm.json.id}/cancelar`, { motivo: 'teste de cancelamento' })).status === 409)
  check('permuta cancelável antes de liquidar', (await call(fin, 'POST', `${TS}/permutas/${pmErr.json.id}/cancelar`, { motivo: 'valor digitado errado' })).json.status === 'CANCELADA')
  check('permuta: edição só em rascunho', (await call(fin, 'PUT', `${TS}/permutas/${pm.json.id}`, { descricao: 'novo texto' })).status === 409)
  check('permutas: resumo por status', (await call(fin, 'GET', `${TS}/permutas`)).json.resumo.some((r: any) => r.status === 'LIQUIDADA' && r.valor === 800))
  check('permuta de outro tenant = 404', (await call(finB, 'GET', `${TS}/permutas/${pm.json.id}`)).status === 404)

  // recibos
  secao('Recibos: 2ª via, cancelamento e gestão')
  const rcbs = await call(fin, 'GET', `${TS}/recibos`)
  check('lista recibos', rcbs.status === 200 && rcbs.json.items.length >= 5)
  const rid = rcPix.json.recibo.id
  const rdet = await call(fin, 'GET', `${TS}/recibos/${rid}`)
  check('detalhe com documento imprimível', rdet.status === 200 && rdet.json.documento.html.includes('RECIBO Nº A-000001') && rdet.json.documento.linhas.join(' ').includes('Maria Bolsista Souza'), rdet.json.documento?.linhas)
  const via2 = await call(fin, 'POST', `${TS}/recibos/${rid}/segunda-via`, { motivo: 'Aluno perdeu' })
  check('2ª via incrementa e marca o documento', via2.status === 200 && via2.json.vias === 2 && via2.json.documento.segundaVia === 2 && via2.json.documento.linhas[1].includes('2ª VIA'))
  const avul = await call(fin, 'POST', `${TS}/recibos`, { pagadorNome: 'Cliente Avulso', valor: 35.5, descricao: 'Taxa de segunda via de histórico', forma: 'DINHEIRO' })
  check('recibo avulso', avul.status === 201 && avul.json.valorExtenso === 'trinta e cinco reais e cinquenta centavos', avul.json.valorExtenso)
  check('cancelar recibo exige motivo', (await call(fin, 'POST', `${TS}/recibos/${avul.json.id}/cancelar`, { motivo: 'x' })).status === 400)
  const canc = await call(fin, 'POST', `${TS}/recibos/${avul.json.id}/cancelar`, { motivo: 'Emitido em duplicidade' })
  check('cancela recibo com aviso de que não estorna', canc.status === 200 && canc.json.status === 'CANCELADO' && canc.json.aviso.includes('não estorna'))
  check('recibo já cancelado = 409', (await call(fin, 'POST', `${TS}/recibos/${avul.json.id}/cancelar`, { motivo: 'Outra tentativa' })).status === 409)
  const docCanc = await call(fin, 'GET', `${TS}/recibos/${avul.json.id}`)
  check('documento do recibo cancelado marcado', docCanc.json.documento.cancelado === true && docCanc.json.documento.linhas[1].includes('CANCELADO'))
  await prisma.tesRecibo.deleteMany({ where: { tenantId: T, numero: 3 } })   // simula lacuna
  const gest = await call(fin, 'GET', `${TS}/recibos/gestao`)
  check('gestão: cancelados, 2ªs vias e lacunas de numeração', gest.status === 200 && gest.json.cancelados === 1 && gest.json.segundasVias === 1 && gest.json.lacunas.some((l: any) => l.numero === 3), gest.json)
  check('filtro por status e busca', (await call(fin, 'GET', `${TS}/recibos?status=CANCELADO`)).json.total === 1 && (await call(fin, 'GET', `${TS}/recibos?q=Bolsista`)).json.total >= 1)
  check('recibo de outro tenant = 404', (await call(finB, 'GET', `${TS}/recibos/${rid}`)).status === 404 && (await call(finB, 'POST', `${TS}/recibos/${rid}/cancelar`, { motivo: 'invasão de tenant' })).status === 404)

  // ---------------------------------------------------------------- contas a pagar: máquina de estados
  secao('Contas a pagar: rascunho -> conferido -> autorizado, segregação e alçada')
  const cpfFav = cpfValido(123456)
  const novoTit = (o: any = {}) => ({ descricao: 'Manutenção do ar-condicionado', fornecedor: 'Climatiza Serviços Ltda', fornecedorDocumento: '11222333000181', formaPagamento: 'PIX', tipoChavePix: 'CNPJ', chavePix: '11222333000181', contaBancariaId: idB, valorBruto: 1000, vencimento: iso(5), categoria: 'manutenção', ...o })
  const t1r = await call(fin, 'POST', `${TS}/titulos`, novoTit())
  check('cria título em rascunho numerado', t1r.status === 201 && t1r.json.status === 'RASCUNHO' && t1r.json.numero === 'CP-000001' && t1r.json.valorLiquido === 1000, t1r.json)
  const tid1 = t1r.json.id
  check('retenções maiores que o bruto recusadas', (await call(fin, 'POST', `${TS}/titulos`, novoTit({ retencaoIrrf: 2000 }))).status === 400)
  check('valor zero recusado', (await call(fin, 'POST', `${TS}/titulos`, novoTit({ valorBruto: 0 }))).status === 400)
  check('centro de custo de outro tenant recusado', (await call(finB, 'POST', `${TS}/titulos`, novoTit({ centroCustoId: 'inexistente' }))).status === 404)
  check('segregação: quem lançou não confere', (await call(fin, 'POST', `${TS}/titulos/${tid1}/conferir`)).status === 403)
  const segr = await call(fin, 'POST', `${TS}/titulos/${tid1}/conferir`)
  check('código de erro SEGREGACAO', segr.json.code === 'SEGREGACAO')
  check('não é possível autorizar rascunho', (await call(coord, 'POST', `${TS}/titulos/${tid1}/autorizar`)).status === 409)
  const incompleto = await call(fin, 'POST', `${TS}/titulos`, novoTit({ chavePix: undefined, tipoChavePix: undefined, descricao: 'Título sem chave Pix' }))
  const confInc = await call(coord, 'POST', `${TS}/titulos/${incompleto.json.id}/conferir`)
  check('conferência recusa dados de pagamento incompletos', confInc.status === 422 && confInc.json.code === 'DADOS_INCOMPLETOS' && confInc.json.pendencias.length > 0, confInc.json)
  check('edita rascunho e depois confere', (await call(fin, 'PUT', `${TS}/titulos/${incompleto.json.id}`, { chavePix: '11222333000181', tipoChavePix: 'CNPJ' })).status === 200 && (await call(coord, 'POST', `${TS}/titulos/${incompleto.json.id}/conferir`)).status === 200)
  const cf = await call(coord, 'POST', `${TS}/titulos/${tid1}/conferir`, { observacao: 'Nota conferida' })
  check('coordenador confere', cf.status === 200 && cf.json.status === 'CONFERIDO' && cf.json.conferidoPorId === coord.id)
  check('conferir de novo = 409', (await call(coord2, 'POST', `${TS}/titulos/${tid1}/conferir`)).status === 409)
  check('título conferido não pode ser editado', (await call(fin, 'PUT', `${TS}/titulos/${tid1}`, { valorBruto: 1 })).status === 409)
  check('segregação: quem lançou não autoriza', (await call(fin, 'POST', `${TS}/titulos/${tid1}/autorizar`)).json.code === 'SEGREGACAO')
  const fila = await call(coord2, 'GET', `${TS}/titulos/fila`)
  check('fila mostra o que o coordenador pode agir', fila.status === 200 && fila.json.aAutorizar >= 1 && fila.json.items.find((i: any) => i.id === tid1)?.podeAutorizar === true && fila.json.items.find((i: any) => i.id === tid1).aprovacoesNecessarias === 1, fila.json.items?.[0])
  const filaFin = await call(fin, 'GET', `${TS}/titulos/fila`)
  check('fila do lançador: não pode conferir/autorizar o próprio', filaFin.json.items.find((i: any) => i.id === tid1).podeAutorizar === false)
  const au = await call(coord2, 'POST', `${TS}/titulos/${tid1}/autorizar`)
  check('coordenador autoriza valor até R$ 5.000', au.status === 200 && au.json.titulo.status === 'AUTORIZADO' && au.json.aprovacoesFeitas === 1 && !!au.json.titulo.accountPayableId && !!au.json.titulo.hashAutorizado, au.json)
  check('cria conta a pagar no financeiro ao autorizar', (await prisma.accountPayable.findUnique({ where: { id: au.json.titulo.accountPayableId } }))?.valor === 1000)
  check('autorizar de novo = 409', (await call(coord, 'POST', `${TS}/titulos/${tid1}/autorizar`)).status === 409)
  check('autorizado não pode ser editado', (await call(fin, 'PUT', `${TS}/titulos/${tid1}`, { valorBruto: 5 })).status === 409)

  // alçadas
  const t2m = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Reforma do laboratório', valorBruto: 12000 }))
  await call(coord, 'POST', `${TS}/titulos/${t2m.json.id}/conferir`)
  const alc1 = await call(coord2, 'POST', `${TS}/titulos/${t2m.json.id}/autorizar`)
  check('alçada: coordenador não autoriza R$ 12.000', alc1.status === 403 && alc1.json.code === 'ALCADA', alc1.json)
  check('alçada: outro financeiro autoriza R$ 12.000', (await call(fin2, 'POST', `${TS}/titulos/${t2m.json.id}/autorizar`)).json.titulo.status === 'AUTORIZADO')
  const tAlta = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Compra de equipamentos', valorBruto: 45000, fornecedor: 'Equipamentos Médicos SA' }))
  await call(coord, 'POST', `${TS}/titulos/${tAlta.json.id}/conferir`)
  check('acima de R$ 20.000 financeiro não autoriza', (await call(fin2, 'POST', `${TS}/titulos/${tAlta.json.id}/autorizar`)).json.code === 'ALCADA')
  const ap1 = await call(admin, 'POST', `${TS}/titulos/${tAlta.json.id}/autorizar`)
  check('dupla aprovação: 1ª aprovação mantém CONFERIDO', ap1.status === 200 && ap1.json.aguardandoSegundaAprovacao === true && ap1.json.titulo.status === 'CONFERIDO' && ap1.json.aprovacoesNecessarias === 2, ap1.json)
  const ap1b = await call(admin, 'POST', `${TS}/titulos/${tAlta.json.id}/autorizar`)
  check('dupla aprovação: mesma pessoa não aprova duas vezes', ap1b.status === 403 && ap1b.json.code === 'DUPLA_APROVACAO', ap1b.json)
  const ap2 = await call(rector, 'POST', `${TS}/titulos/${tAlta.json.id}/autorizar`)
  check('dupla aprovação: 2º aprovador conclui', ap2.status === 200 && ap2.json.titulo.status === 'AUTORIZADO' && ap2.json.aprovacoesFeitas === 2)
  const detAlta = await call(fin, 'GET', `${TS}/titulos/${tAlta.json.id}`)
  check('detalhe traz aprovações e trilha completa', detAlta.json.aprovacoes.filter((a: any) => a.tipo === 'AUTORIZACAO').length === 2 && detAlta.json.eventos.map((e: any) => e.acao).join(',') === 'CRIADO,CONFERIDO,APROVACAO_PARCIAL,AUTORIZADO', detAlta.json.eventos.map((e: any) => e.acao))
  const trilha = await call(fin, 'GET', `${TS}/titulos/${tAlta.json.id}/trilha`)
  check('trilha inclui auditoria global (EduAuditEvent)', trilha.status === 200 && trilha.json.auditoria.some((a: any) => a.acao === 'TITULO_AUTORIZADO') && trilha.json.eventos.length === 4)
  check('limite de dupla aprovação configurável', (await call(fin, 'PUT', `${TS}/config`, { limiteDuplaAprovacao: 500 })).status === 200)
  const tDupla = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Material de limpeza', valorBruto: 800 }))
  await call(coord, 'POST', `${TS}/titulos/${tDupla.json.id}/conferir`)
  const dup1 = await call(coord2, 'POST', `${TS}/titulos/${tDupla.json.id}/autorizar`)
  check('limite global de dupla aprovação vale mesmo na faixa de 1 aprovador', dup1.json.aguardandoSegundaAprovacao === true && dup1.json.aprovacoesNecessarias === 2)
  check('o mesmo aprovador não conclui a dupla aprovação', (await call(coord2, 'POST', `${TS}/titulos/${tDupla.json.id}/autorizar`)).json.code === 'DUPLA_APROVACAO')
  check('2º aprovador (conferente, alçada da faixa) conclui', (await call(coord, 'POST', `${TS}/titulos/${tDupla.json.id}/autorizar`)).json.titulo.status === 'AUTORIZADO')
  await call(fin, 'PUT', `${TS}/config`, { limiteDuplaAprovacao: 20000 })
  const hmod = await call(admin, 'PUT', `${TS}/alcadas`, { faixas: [{ nome: 'Coordenação até 2 mil', valorAte: 2000, papeis: ['COORDINATOR'], aprovacoes: 1 }, { nome: 'Diretoria', valorAte: null, papeis: ['RECTOR'], aprovacoes: 1 }] })
  check('diretoria personaliza alçadas', hmod.status === 200 && hmod.json.alcadas.length === 2)
  const tCustom = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Serviço de jardinagem', valorBruto: 3000 }))
  await call(coord, 'POST', `${TS}/titulos/${tCustom.json.id}/conferir`)
  check('alçada personalizada: coordenador não passa de 2 mil', (await call(coord2, 'POST', `${TS}/titulos/${tCustom.json.id}/autorizar`)).json.code === 'ALCADA')
  check('alçada personalizada: reitor autoriza', (await call(rector, 'POST', `${TS}/titulos/${tCustom.json.id}/autorizar`)).json.titulo.status === 'AUTORIZADO')
  check('restaura alçadas padrão', (await call(admin, 'DELETE', `${TS}/alcadas`)).json.alcadasPadrao === true)

  // rejeitar, devolver, cancelar, lote
  secao('Rejeitar, devolver, cancelar e lote')
  const tRej = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Despesa sem comprovante', valorBruto: 300 }))
  await call(coord, 'POST', `${TS}/titulos/${tRej.json.id}/conferir`)
  check('rejeitar exige motivo', (await call(coord2, 'POST', `${TS}/titulos/${tRej.json.id}/rejeitar`, { motivo: 'x' })).status === 400)
  const rej = await call(coord2, 'POST', `${TS}/titulos/${tRej.json.id}/rejeitar`, { motivo: 'Sem nota fiscal anexa' })
  check('coordenador rejeita com motivo', rej.status === 200 && rej.json.status === 'REJEITADO' && rej.json.motivoRejeicao === 'Sem nota fiscal anexa')
  check('rejeitado volta a rascunho ao ser editado', (await call(fin, 'PUT', `${TS}/titulos/${tRej.json.id}`, { descricao: 'Despesa com comprovante' })).json.status === 'RASCUNHO')
  const tDev = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Título para devolver', valorBruto: 400 }))
  await call(coord, 'POST', `${TS}/titulos/${tDev.json.id}/conferir`)
  const auDev = await call(coord2, 'POST', `${TS}/titulos/${tDev.json.id}/autorizar`)
  const apDev = auDev.json.titulo.accountPayableId
  const dev = await call(coord2, 'POST', `${TS}/titulos/${tDev.json.id}/devolver`, { motivo: 'Valor precisa ser revisto' })
  check('devolver autorizado volta a rascunho e cancela a conta a pagar', dev.status === 200 && dev.json.status === 'RASCUNHO' && dev.json.hashAutorizado === null && (await prisma.accountPayable.findUnique({ where: { id: apDev } }))?.status === 'CANCELADO')
  check('devolução limpa aprovações', (await prisma.tesAprovacao.count({ where: { tituloId: tDev.json.id } })) === 0)
  const tCan = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Título para cancelar', valorBruto: 50 }))
  check('cancelar rascunho pelo lançador', (await call(fin, 'POST', `${TS}/titulos/${tCan.json.id}/cancelar`, { motivo: 'Lançado por engano' })).json.status === 'CANCELADO')
  check('cancelado é final', (await call(coord, 'POST', `${TS}/titulos/${tCan.json.id}/conferir`)).status === 409)
  const lote = await call(coord, 'POST', `${TS}/titulos/lote`, { acao: 'conferir', ids: [tDev.json.id, tCan.json.id, 'nao-existe'] })
  check('lote: resultados por item sem derrubar o conjunto', lote.status === 200 && lote.json.ok === 1 && lote.json.falhas === 2 && lote.json.resultados[1].ok === false, lote.json)
  const lote2 = await call(coord2, 'POST', `${TS}/titulos/lote`, { acao: 'autorizar', ids: [tDev.json.id] })
  check('lote autoriza (segregação preservada)', lote2.status === 200 && lote2.json.ok === 1 && lote2.json.resultados[0].status === 'AUTORIZADO')
  check('lote: segregação do lançador bloqueia', (await call(fin, 'POST', `${TS}/titulos/lote`, { acao: 'conferir', ids: [tRej.json.id] })).json.resultados[0].code === 'SEGREGACAO')
  check('título de outro tenant = 404', (await call(adminB, 'GET', `${TS}/titulos/${tid1}`)).status === 404 && (await call(adminB, 'POST', `${TS}/titulos/${tid1}/autorizar`)).status === 404 && (await call(finB, 'POST', `${TS}/titulos/${tid1}/cancelar`, { motivo: 'invasão de tenant' })).status === 404)

  // ---------------------------------------------------------------- 2FA em ações sensíveis
  secao('Reautenticação 2FA em valores altos')
  check('configura limite de 2FA', (await call(fin, 'PUT', `${TS}/config`, { exige2faAcima: 2500 })).status === 200)
  const t2fa = await call(fin, 'POST', `${TS}/titulos`, novoTit({ descricao: 'Pagamento sensível', valorBruto: 4000 }))
  await call(coord, 'POST', `${TS}/titulos/${t2fa.json.id}/conferir`)
  const sem2fa = await call(coord2, 'POST', `${TS}/titulos/${t2fa.json.id}/autorizar`)
  check('sem 2FA ativo o usuário é barrado', sem2fa.status === 403 && sem2fa.json.code === '2FA_NAO_CONFIGURADO', sem2fa.json)
  const userCoord2 = await prisma.user.findUniqueOrThrow({ where: { id: coord2.id } })
  const cfg2 = await iniciarConfiguracao({ id: userCoord2.id, tenantId: T, email: userCoord2.email })
  const codConf = totp(base32Decode(cfg2.secret), Date.now() - 30_000)
  const codigosRec = await confirmarConfiguracao(userCoord2.id, codConf)
  check('2FA do coordenador ativado (códigos de recuperação)', Array.isArray(codigosRec) && codigosRec!.length === 8)
  const faltaCod = await call(coord2, 'POST', `${TS}/titulos/${t2fa.json.id}/autorizar`)
  check('com 2FA ativo exige o código', faltaCod.status === 403 && faltaCod.json.code === '2FA_REQUERIDO')
  const codErr = await call(coord2, 'POST', `${TS}/titulos/${t2fa.json.id}/autorizar`, { codigo2fa: '000000' })
  check('código inválido recusado', codErr.status === 403 && codErr.json.code === '2FA_INVALIDO')
  const ok2fa = await call(coord2, 'POST', `${TS}/titulos/${t2fa.json.id}/autorizar`, { codigo2fa: codigosRec![0] })
  check('código válido autoriza e registra uso do 2FA', ok2fa.status === 200 && ok2fa.json.titulo.status === 'AUTORIZADO' && (await prisma.tesAprovacao.findFirst({ where: { tituloId: t2fa.json.id, tipo: 'AUTORIZACAO' } }))?.usou2fa === true, ok2fa.json)
  check('valor abaixo do limite não pede 2FA', (await call(fin, 'GET', `${TS}/titulos/${tDev.json.id}`)).json.exige2fa === false)

  // ---------------------------------------------------------------- remessas
  secao('Remessas: CNAB 240, Pix em lote, provedor simulado, retorno')
  const preparar = async (o: any) => {
    const t = await call(fin, 'POST', `${TS}/titulos`, novoTit(o))
    await call(coord, 'POST', `${TS}/titulos/${t.json.id}/conferir`)
    const a = await call(coord2, 'POST', `${TS}/titulos/${t.json.id}/autorizar`, { codigo2fa: codigosRec![1] })
    return { id: t.json.id as string, aut: a }
  }
  await call(fin, 'PUT', `${TS}/config`, { exige2faAcima: null })
  const pPix = await preparar({ descricao: 'Pagamento Pix lote', fornecedor: 'João da Silva', fornecedorDocumento: cpfFav, tipoChavePix: 'CPF', chavePix: cpfFav, valorBruto: 1200 })
  const pTed = await preparar({ descricao: 'Pagamento TED lote', fornecedor: 'Papelaria Central Ltda', formaPagamento: 'TED', favorecidoBanco: '001', favorecidoAgencia: '4321', favorecidoConta: '98765-4', valorBruto: 2300.75, chavePix: undefined, tipoChavePix: undefined })
  const pBol = await preparar({ descricao: 'Boleto energia', fornecedor: 'Energia SA', formaPagamento: 'BOLETO', codigoBarras: '23793381286000000000300000000403456780000012345', valorBruto: 900, fornecedorDocumento: undefined, chavePix: undefined, tipoChavePix: undefined })
  const pRej = await preparar({ descricao: 'Pix chave com problema', fornecedor: 'Fornecedor Problema', tipoChavePix: 'EMAIL', chavePix: 'rejeitar@fornecedor.com', fornecedorDocumento: undefined, valorBruto: 150 })
  const pTed0 = await preparar({ descricao: 'TED conta inválida', fornecedor: 'Conta Zero Ltda', formaPagamento: 'TED', favorecidoBanco: '237', favorecidoAgencia: '1', favorecidoConta: '120000', valorBruto: 70, chavePix: undefined, tipoChavePix: undefined })
  check('títulos preparados e autorizados', [pPix, pTed, pBol, pRej, pTed0].every((p) => p.aut.status === 200 && p.aut.json.titulo.status === 'AUTORIZADO'), [pPix.aut.json, pTed.aut.json, pBol.aut.json])
  const eleg = await call(fin, 'GET', `${TS}/remessas/elegiveis?contaId=${idB}`)
  check('elegíveis: autorizados da conta, íntegros', eleg.status === 200 && eleg.json.items.length >= 5 && eleg.json.items.every((i: any) => i.integridadeOk))
  check('conta sem dados completos recusa remessa', (await call(fin, 'POST', `${TS}/remessas`, { contaId: idB2, tipo: 'CNAB240' })).status === 422)
  check('caixa não gera remessa', (await call(fin, 'POST', `${TS}/remessas`, { contaId: idCx })).status === 409)
  const idsRem = [pPix.id, pTed.id, pBol.id, pRej.id, pTed0.id]
  check('segregação do remessa: coordenador não gera', (await call(coord, 'POST', `${TS}/remessas`, { contaId: idB, tituloIds: idsRem })).status === 403)
  check('título inexistente na remessa recusado', (await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tituloIds: [...idsRem, 'xx'] })).json.code === 'TITULOS_INELEGIVEIS')
  const rem = await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tipo: 'CNAB240', tituloIds: idsRem, dataPagamento: iso(0) })
  check('gera remessa CNAB 240 com 5 itens', rem.status === 201 && rem.json.numero === 1 && rem.json.qtd === 5 && rem.json.valorTotal === 1200 + 2300.75 + 900 + 150 + 70 && rem.json.status === 'GERADA' && rem.json.nomeArquivo.endsWith('.REM'), rem.json.valorTotal)
  const linhasRem = rem.json.conteudo.split('\r\n').filter(Boolean)
  check('arquivo gerado válido (240 posições, hash)', linhasRem.every((l: string) => l.length === 240) && rem.json.hash.length === 64 && linhasRem[0].startsWith('341'))
  check('itens com identificador fim-a-fim', rem.json.itens.every((i: any) => /^R000001T\d{4}$/.test(i.idPagamento)))
  check('títulos reservados na remessa (não elegíveis de novo)', (await call(fin, 'GET', `${TS}/remessas/elegiveis?contaId=${idB}`)).json.items.every((i: any) => !idsRem.includes(i.id)))
  check('título em remessa não devolve', (await call(coord, 'POST', `${TS}/titulos/${pPix.id}/devolver`, { motivo: 'tentar devolver' })).json.code === 'EM_REMESSA')
  check('título em remessa não cancela', (await call(coord, 'POST', `${TS}/titulos/${pPix.id}/cancelar`, { motivo: 'tentar cancelar' })).json.code === 'EM_REMESSA')
  check('detalhe da remessa traz títulos', (await call(fin, 'GET', `${TS}/remessas/${rem.json.id}`)).json.itens[0].titulo.numero.startsWith('CP-'))
  check('nova remessa sem elegíveis = 409', (await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tituloIds: [pPix.id] })).status === 409)
  // integridade: altera valor direto no banco e tenta enviar
  await prisma.tesTitulo.update({ where: { id: pBol.id }, data: { valorLiquido: 1, valorBruto: 1 } })
  const envInt = await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/enviar`)
  check('integridade: alteração pós-autorização bloqueia o envio', envInt.status === 409 && envInt.json.code === 'INTEGRIDADE', envInt.json)
  await prisma.tesTitulo.update({ where: { id: pBol.id }, data: { valorLiquido: 900, valorBruto: 900 } })
  check('retorno antes do envio = 409', (await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/consultar-retorno`)).status === 409)
  const env = await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/enviar`)
  check('envia ao banco (simulado) e devolve protocolo', env.status === 200 && env.json.simulado === true && env.json.remessa.status === 'ENVIADA' && /^SIM-/.test(env.json.remessa.protocolo), env.json)
  check('títulos passam a ENVIADO_BANCO', (await prisma.tesTitulo.count({ where: { id: { in: idsRem }, status: 'ENVIADO_BANCO' } })) === 5)
  check('reenvio = 409', (await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/enviar`)).status === 409)
  check('remessa enviada não cancela', (await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/cancelar`, { motivo: 'cancelar após envio' })).status === 409)
  const retC = await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/consultar-retorno`)
  check('retorno do simulador: 3 pagos e 2 rejeitados', retC.status === 200 && retC.json.pagos === 3 && retC.json.rejeitados === 2 && retC.json.status === 'PROCESSADA', retC.json)
  check('pagos baixados; rejeitados voltam a AUTORIZADO com motivo', (await prisma.tesTitulo.count({ where: { id: { in: [pPix.id, pTed.id, pBol.id] }, status: 'PAGO' } })) === 3 && (await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pRej.id } })).status === 'AUTORIZADO' && !!(await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pRej.id } })).ultimoErroBanco && (await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pRej.id } })).remessaId === null)
  check('baixa criou saída no banco e conta a pagar paga', (await prisma.tesMovimento.count({ where: { tenantId: T, refTipo: 'TITULO', refId: pPix.id, valor: -1200 } })) === 1 && (await prisma.accountPayable.findUnique({ where: { id: pPix.aut.json.titulo.accountPayableId } }))?.status === 'PAGO')
  check('retorno repetido é idempotente', (await call(fin, 'POST', `${TS}/remessas/${rem.json.id}/consultar-retorno`)).status === 409)
  const trilhaPix = await call(fin, 'GET', `${TS}/titulos/${pPix.id}/trilha`)
  check('trilha do título pago: incluído, enviado, pago', ['INCLUIDO_REMESSA', 'ENVIADO_BANCO', 'PAGO'].every((a) => trilhaPix.json.eventos.some((e: any) => e.acao === a)))
  // reenvio dos rejeitados via Pix em lote e retorno manual
  await prisma.tesTitulo.update({ where: { id: pRej.id }, data: { chavePix: 'ok@fornecedor.com', hashAutorizado: hashAutorizacao({ ...(await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pRej.id } })), chavePix: 'ok@fornecedor.com' }) } })
  const remPix = await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tipo: 'PIX_LOTE', tituloIds: [pRej.id] })
  check('Pix em lote gera CSV', remPix.status === 201 && remPix.json.tipo === 'PIX_LOTE' && remPix.json.nomeArquivo.endsWith('.csv') && remPix.json.conteudo.includes('ok@fornecedor.com'))
  check('Pix em lote recusa TED', (await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tipo: 'PIX_LOTE', tituloIds: [pTed0.id] })).status === 409)
  const envPix = await call(fin, 'POST', `${TS}/remessas/${remPix.json.id}/enviar`)
  const retMan = await call(fin, 'POST', `${TS}/remessas/${remPix.json.id}/retorno`, { conteudo: `${remPix.json.itens[0].idPagamento};PAGO;\r\n` })
  check('retorno manual (CSV) baixa o título', envPix.status === 200 && retMan.status === 200 && retMan.json.pagos === 1 && (await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pRej.id } })).status === 'PAGO')
  // cancelar remessa gerada libera títulos
  const remCan = await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tipo: 'CNAB240', tituloIds: [pTed0.id] })
  check('cancela remessa GERADA e libera títulos', remCan.status === 201 && (await call(fin, 'POST', `${TS}/remessas/${remCan.json.id}/cancelar`, { motivo: 'Gerada por engano' })).json.status === 'CANCELADA' && (await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pTed0.id } })).remessaId === null)
  // arquivo rejeitado pelo banco simulado
  const remRejArq = await call(fin, 'POST', `${TS}/remessas`, { contaId: idB, tipo: 'CNAB240', tituloIds: [pTed0.id] })
  await prisma.tesRemessa.update({ where: { id: remRejArq.json.id }, data: { nomeArquivo: 'REJEITAR.REM' } })
  const envRej = await call(fin, 'POST', `${TS}/remessas/${remRejArq.json.id}/enviar`)
  check('arquivo rejeitado pelo banco: remessa em ERRO e títulos liberados', envRej.status === 422 && envRej.json.code === 'REMESSA_REJEITADA' && (await prisma.tesRemessa.findUniqueOrThrow({ where: { id: remRejArq.json.id } })).status === 'ERRO' && (await prisma.tesTitulo.findUniqueOrThrow({ where: { id: pTed0.id } })).status === 'AUTORIZADO')
  // provedor não configurado
